import 'bootstrap/dist/css/bootstrap.min.css' 
import './App.css'
import {Container, Badge, ListGroup,ListGroupItem, Form, Button} from 'react-bootstrap'
import { useState,useEffect } from 'react';
import Axios from 'axios';

function App() {
  const API = "http://localhost:3001/";

  //useState
  const [users, setUsers] = useState([]);
  const [name,setName] = useState("");
  const [age,setAge] = useState("");
  const [email,setEmail] = useState("");

  const [updateId, setUpdateId] = useState("");
  const [updateName, setUpdateName] = useState("");
  const [updateAge, setUpdateAge] = useState("");
  const [updateEmail, setUpdateEmail] = useState("");

  useEffect(()=>{                         
    Axios.get(`${API}`)
    .then(res=>{
      setUsers(res.data);
    });
  },[]);

  const createUser=()=>{
    if(name && age && email){
      Axios.post(`${API}createUser`, {name, age, email})
      .then(res=>{
        setUsers([...users, res.data]);
        setName("");
        setAge("");
        setEmail("");
      })
      .catch(error=>console.error("Error Creating User",error));
    }
  }

  const deleteUser = (id) => {
    Axios.delete(`${API}deleteUser/${id}`)
    .then(() => {
      setUsers(users.filter((user) => user._id !== id));
    })
    .catch(error => console.error("Error Deleting User", error));
  }

  const startUpdate = (_id, name, age, email) => {
    setUpdateId(_id);
    setUpdateName(name);
    setUpdateAge(age);
    setUpdateEmail(email);
  }

  const updateUser = () => {
    if(updateName && updateAge && updateEmail){
      Axios.put(`${API}updateUser/${updateId}`, {
        name: updateName,
        age: updateAge,
        email: updateEmail
      })
      .then(res => {
        const updatedUsers = users.map((user) => {
          if(user._id === updateId){
            return res.data;
          } else {
            return user;
          }
        });

        setUsers(updatedUsers);
        setUpdateId("");
        setUpdateName("");
        setUpdateAge("");
        setUpdateEmail("");
      })
      .catch(error => console.error("Error Updating User", error));
    }
  }

  return (
    <Container>
      <Form className='form'>
        <Form.Control 
          type="text" 
          placeholder='Name'
          value={name}
          onChange={e=>setName(e.target.value)} 
        />

        <Form.Control  
          type="number" 
          placeholder='Age'
          value={age}
          onChange={e=>setAge(e.target.value)} 
        />

        <Form.Control 
          type="text" 
          placeholder="Email"
          value={email}
          onChange={e=>setEmail(e.target.value)} 
        />

        <button type="button" onClick={createUser}>Create User</button>
      </Form>

      {updateId && (
        <Form className='form'>
          <Form.Control 
            type="text" 
            placeholder='Update Name'
            value={updateName}
            onChange={e=>setUpdateName(e.target.value)} 
          />

          <Form.Control  
            type="number" 
            placeholder='Update Age'
            value={updateAge}
            onChange={e=>setUpdateAge(e.target.value)} 
          />

          <Form.Control 
            type="text" 
            placeholder="Update Email"
            value={updateEmail}
            onChange={e=>setUpdateEmail(e.target.value)} 
          />

          <button type="button" onClick={updateUser}>Update User</button>
        </Form>
      )}

      <div className='result'>
        {users.map(({_id, name, age, email})=>{
          return(
            <ListGroup key={_id}>
              <ListGroupItem variant='dark' className='d-flex justify-content-sm-between'>
                <div className='ms2 me-auto'>
                  <div className='fw-bold'>{name}</div>{email}
                </div>

                <div>
                  <Badge bg='badge bg-success' pill>{age}</Badge>
                </div>

                <div>
                  <Button 
                    variant="warning" 
                    onClick={() => startUpdate(_id, name, age, email)}
                  >
                    Update
                  </Button>

                  <Button 
                    variant="danger" 
                    onClick={() => deleteUser(_id)}
                  >
                    Delete
                  </Button>
                </div>
              </ListGroupItem>
            </ListGroup>      
          );
        })}
      </div>
    </Container>
  );
}

export default App;
